from cs_lib import *
C = '6th Grade Math'

sheet('math6-ratios-rates-percent-proportions', C, 1, 'Ratios, Rate, Percent and Proportions',
  'ratios, unit rates, equivalent ratios and tables', 'proportions, percents and unit conversions',
  [V('Key Vocabulary', [
     ['ratio', 'Compares two quantities.', r'3 to 5, 3 : 5, ⟨\tfrac{3}{5}⟩'],
     ['rate', 'A ratio of two different units.', '150 miles in 3 hours'],
     ['unit rate', 'A rate for 1 unit.', '50 miles per hour'],
     ['equivalent ratios', 'Same comparison; multiply or divide both parts by the same number.', '2 : 3 = 8 : 12'],
     ['proportion', 'Two equal ratios.', r'⟨\tfrac{2}{5} = \tfrac{6}{15}⟩']]),
   EX('Finding a Unit Rate', 'Divide the first quantity by the second so the second becomes 1.',
      '$7.20 for 6 pounds of apples. Price per pound?', [['Divide:', r'⟨\tfrac{7.20}{6} = 1.20⟩']], '$1.20 per pound', N('7.20/6', 1.2)),
   TB('Ratio Tables', ['Cups of flour', 'Cookies'], [['2', '24'], ['4', '48'], ['6', '72'], ['1', '12']],
      'Multiply or divide BOTH columns by the same number. Each row is an equivalent ratio.', [N('24/2', 12), N('72/6', 12)]),
   EX('Comparing Ratios', 'Write each as a unit rate (or find a common term), then compare.',
      'Which is the better buy: 12 oz for $3 or 20 oz for $4.40?', [['Unit prices:', r'⟨\tfrac{3}{12} = 0.25⟩, ⟨\tfrac{4.40}{20} = 0.22⟩ dollars per oz']],
      '20 oz for $4.40', [N('3/12', 0.25), N('4.40/20', 0.22)]),
   EX('Solving a Proportion', 'Use equivalent ratios or cross products.',
      r'⟨\tfrac{3}{4} = \tfrac{x}{20}⟩', [['Scale:', r'4 × 5 = 20, so 3 × 5 = ⟨x⟩']], '⟨x = 15⟩', N('3*20/4', 15)),
   MS('Quick Reminders & Common Mistakes', ['Order matters: 3 boys to 5 girls is 3 : 5, not 5 : 3.', 'Units belong in the answer of a rate.', 'A unit rate always has 1 in the second quantity.'],
      [['Adding to both parts: 2 : 3 → 4 : 5', 'multiply, do not add'], ['Dividing the wrong way for a unit price', 'price ÷ amount'], ['Mixing units', 'convert first']])],
  [TB('Percent Basics', ['Percent', 'Fraction / decimal'], [['50%', r'⟨\tfrac{1}{2}⟩ = 0.5'], ['25%', r'⟨\tfrac{1}{4}⟩ = 0.25'], ['10%', r'⟨\tfrac{1}{10}⟩ = 0.1'], ['75%', r'⟨\tfrac{3}{4}⟩ = 0.75'], ['120%', '1.2']],
      'Percent means “per 100.”'),
   EX('Percent of a Number', 'Change the percent to a decimal, then multiply.', 'Find 35% of 80.', [['Decimal:', '35% = 0.35'], ['Multiply:', '0.35 × 80']], '28', N('0.35*80', 28)),
   EX('Finding the Whole', 'part = percent × whole, so whole = part ÷ percent.', '18 is 30% of what number?', [['Divide:', r'⟨\tfrac{18}{0.30}⟩']], '60', N('18/0.30', 60)),
   EX('A Fraction as a Percent', 'Make the denominator 100, or divide and multiply by 100.', r'Write ⟨\tfrac{7}{20}⟩ as a percent.', [['Scale:', r'⟨\tfrac{7}{20} = \tfrac{35}{100}⟩']], '35%', N('7/20*100', 35)),
   TB('Converting Units', ['Conversion', 'Use the ratio'], [['1 ft = 12 in', r'⟨\tfrac{12 \text{ in}}{1 \text{ ft}}⟩'], ['1 yd = 3 ft', r'⟨\tfrac{3 \text{ ft}}{1 \text{ yd}}⟩'], ['1 gal = 4 qt', r'⟨\tfrac{4 \text{ qt}}{1 \text{ gal}}⟩'], ['1 m = 100 cm', r'⟨\tfrac{100 \text{ cm}}{1 \text{ m}}⟩']],
      'Example: 5 ft × 12 in per ft = 60 in.', N('5*12', 60)),
   L('Check Yourself', ['Did I write the ratio in the order the words say?', 'Is my unit rate “per 1”?', 'Does my percent answer make sense (less than the whole when under 100%)?', 'Did my units cancel when converting?'])])

sheet('math6-fractions-decimals-operations', C, 2, 'Operations of Fractions and Decimals',
  'dividing fractions and mixed numbers', 'multi-digit decimals, GCF, LCM and the distributive property',
  [V('Key Vocabulary', [
     ['reciprocal', 'Flip a fraction; the product is 1.', r'⟨\tfrac{3}{5}⟩ and ⟨\tfrac{5}{3}⟩'],
     ['quotient', 'The answer to a division.', '12 ÷ 4 = 3'],
     ['mixed number', 'A whole number and a fraction.', r'⟨2\tfrac{1}{3}⟩'],
     ['dividend / divisor', 'In a ÷ b, a is the dividend, b the divisor.', '36 ÷ 4'],
     ['improper fraction', 'Numerator greater than or equal to the denominator.', r'⟨\tfrac{7}{3}⟩']]),
   EX('Dividing Fractions', 'Keep the first fraction, change ÷ to ×, flip the second.', r'⟨\tfrac{3}{4} \div \tfrac{2}{5}⟩', [['Flip and multiply:', r'⟨\tfrac{3}{4} \times \tfrac{5}{2} = \tfrac{15}{8}⟩']], r'⟨\tfrac{15}{8} = 1\tfrac{7}{8}⟩', N('(3/4)/(2/5)', 1.875)),
   EX('Whole Numbers and Fractions', 'Write the whole number over 1 first.', r'⟨6 \div \tfrac{3}{4}⟩', [['Rewrite:', r'⟨\tfrac{6}{1} \times \tfrac{4}{3} = \tfrac{24}{3}⟩']], '8', N('6/(3/4)', 8)),
   EX('Mixed Numbers', 'Change mixed numbers to improper fractions before dividing.', r'⟨2\tfrac{1}{2} \div 1\tfrac{1}{4}⟩', [['Improper:', r'⟨\tfrac{5}{2} \div \tfrac{5}{4}⟩'], ['Flip:', r'⟨\tfrac{5}{2} \times \tfrac{4}{5} = 2⟩']], '2', N('2.5/1.25', 2)),
   EX('Long Division', 'Divide, multiply, subtract, bring down. Repeat.', '1,428 ÷ 12', [['12 into 14:', '1 R 2, bring down 2 → 22'], ['Continue:', '22 → 1 R 10, 108 → 9']], '119', N('1428/12', 119)),
   MS('Quick Reminders & Common Mistakes', ['Only flip the SECOND fraction.', 'Dividing by a fraction less than 1 makes the answer bigger.', 'Simplify before multiplying when you can.'],
      [[r'Flipping the first fraction', 'keep, change, flip the second'], ['Dividing mixed numbers part by part', 'convert to improper first'], ['Forgetting to simplify', r'⟨\tfrac{8}{12} = \tfrac{2}{3}⟩']])],
  [EX('Adding and Subtracting Decimals', 'Line up the decimal points; add zeros as placeholders.', '23.5 − 7.28', [['Line up:', '23.50 − 7.28']], '16.22', N('23.5-7.28', 16.22)),
   EX('Multiplying Decimals', 'Multiply as whole numbers, then count the decimal places in both factors.', '3.4 × 0.25', [['Whole numbers:', '34 × 25 = 850'], ['3 decimal places:', '0.850']], '0.85', N('3.4*0.25', 0.85)),
   EX('Dividing Decimals', 'Move the decimal in the divisor to make it whole; move the dividend the same number of places.', '7.56 ÷ 0.6', [['Shift one place:', '75.6 ÷ 6']], '12.6', N('7.56/0.6', 12.6)),
   TB('GCF and LCM', ['Find', 'Example: 12 and 18'], [['Factors of each', '12: 1, 2, 3, 4, 6, 12 · 18: 1, 2, 3, 6, 9, 18'], ['GCF (greatest common factor)', '6'], ['Multiples', '12, 24, 36 … · 18, 36 …'], ['LCM (least common multiple)', '36']],
      'GCF: sharing equally. LCM: when things line up again.', [N('12*18/6', 36)]),
   EX('The Distributive Property', 'Use the GCF to factor a sum: a·b + a·c = a(b + c).', 'Write 24 + 36 as a product using the GCF.', [['GCF of 24 and 36:', '12'], ['Factor:', '12(2 + 3)']], '12(2 + 3)', N('12*(2+3)', 60)),
   L('Check Yourself', ['Did I flip only the divisor?', 'Did I line up the decimal points?', 'Does my decimal answer have the right number of places?', 'Is my GCF a factor of BOTH numbers?'])])

sheet('math6-rational-numbers', C, 3, 'Rational Numbers',
  'positive and negative numbers, the number line, comparing and ordering', 'absolute value and the coordinate plane',
  [V('Key Vocabulary', [
     ['integer', 'A whole number or its opposite.', '−4, 0, 7'],
     ['opposites', 'Same distance from 0, opposite sides.', '5 and −5'],
     ['rational number', 'Can be written as a fraction of integers.', r'⟨-\tfrac{3}{4}⟩, 0.5, −2'],
     ['absolute value', 'Distance from 0 (never negative).', '|−8| = 8'],
     ['ordered pair', '(x, y) gives a point’s location.', '(−3, 2)']]),
   TB('Positive and Negative in Context', ['Situation', 'Number'], [['10 feet below sea level', '−10'], ['A deposit of $25', '+25'], ['4 degrees below zero', '−4'], ['A gain of 6 yards', '+6']]),
   EX('Comparing on a Number Line', 'Numbers increase to the right. The number farther right is greater.', 'Compare −7 and −3.', [['Position:', '−3 is to the right of −7']], '−7 < −3', TRUE('-7 < -3')),
   EX('Ordering Rational Numbers', 'Change to decimals, then place them on a number line.', r'Order ⟨-1.5,\ \tfrac{1}{2},\ -\tfrac{3}{4},\ 0⟩ from least to greatest.', [['Decimals:', '−1.5, 0.5, −0.75, 0']], r'⟨-1.5,\ -\tfrac{3}{4},\ 0,\ \tfrac{1}{2}⟩', TRUE('-1.5 < -0.75 && -0.75 < 0 && 0 < 0.5')),
   W('Inequality Statements', [['The temperature is at least −5°F.', 't ≥ −5'], ['The depth is less than −20 m.', 'd < −20'], ['−2 is greater than −9.', '−2 > −9']], TRUE('-2 > -9')),
   MS('Quick Reminders & Common Mistakes', ['Every negative number is less than every positive number.', 'Opposites have the same absolute value.', '0 is neither positive nor negative.'],
      [['−8 > −2 because 8 > 2', '−8 is farther left, so −8 < −2'], ['|−6| = −6', 'distance is positive: 6'], ['Reading (x, y) as (y, x)', 'x first: across, then up or down']])],
  [EX('Absolute Value', 'Count the distance from 0 on a number line.', 'Find |−12| + |5|.', [['Distances:', '12 and 5']], '17', N('Math.abs(-12)+Math.abs(5)', 17)),
   W('Absolute Value in Context', [['An account balance of −$30 is a debt of …', '$30'], ['Which is farther from 0: −9 or 7?', '−9'], ['Elevation −45 m is how far below sea level?', '45 m']], N('Math.abs(-9)', 9)),
   TB('The Four Quadrants', ['Quadrant', 'Signs (x, y)'], [['I', '(+, +)'], ['II', '(−, +)'], ['III', '(−, −)'], ['IV', '(+, −)']], 'Points on an axis are in no quadrant.'),
   EX('Reflections', 'Reflect over the x-axis: change the sign of y. Over the y-axis: change the sign of x.', 'Reflect (4, −3) over the y-axis.', [['Change x:', '4 → −4']], '(−4, −3)', N('-4', -4)),
   EX('Distance on a Grid', 'Same x or same y: subtract the other coordinates and take the absolute value.', 'Distance from (2, −5) to (2, 3)?', [['Same x:', '|3 − (−5)|']], '8 units', N('Math.abs(3-(-5))', 8)),
   L('Check Yourself', ['Did I use the number line to compare negatives?', 'Is my absolute value a distance (not negative)?', 'Did I move across (x) before up or down (y)?', 'Does my sign match the context (above or below, gain or loss)?'])])

sheet('math6-expressions-equations', C, 4, 'Expressions and Equations',
  'exponents, the order of operations and algebraic expressions', 'equivalent expressions, one-step equations and variables',
  [V('Key Vocabulary', [
     ['exponent', 'How many times the base is a factor.', r'⟨2^3 = 2 \cdot 2 \cdot 2⟩'],
     ['variable', 'A letter for an unknown number.', 'n'],
     ['coefficient', 'The number multiplied by a variable.', '7 in 7x'],
     ['term', 'Parts of an expression separated by + or −.', '3x and 5 in 3x + 5'],
     ['equation', 'A statement that two expressions are equal.', 'x + 4 = 11']]),
   EX('Exponents', 'Multiply the base by itself, exponent times.', r'Evaluate ⟨4^3⟩ and ⟨(\tfrac{1}{2})^2⟩.', [['Expand:', r'4 · 4 · 4 and ⟨\tfrac{1}{2} \cdot \tfrac{1}{2}⟩']], r'64 and ⟨\tfrac{1}{4}⟩', [N('4**3', 64), N('0.5**2', 0.25)]),
   EX('Order of Operations', 'Parentheses, Exponents, Multiply/Divide left to right, Add/Subtract left to right.', r'⟨18 - 2 \cdot (1 + 2)^2⟩', [['Parentheses:', r'⟨(3)^2 = 9⟩'], ['Multiply:', '2 · 9 = 18'], ['Subtract:', '18 − 18']], '0', N('18-2*(1+2)**2', 0)),
   W('Words to Expressions', [['5 more than a number', 'n + 5'], ['twice a number, decreased by 3', '2n − 3'], ['the quotient of a number and 4', r'⟨\tfrac{n}{4}⟩'], ['8 less than y', 'y − 8']]),
   EX('Evaluating Expressions', 'Substitute the value, then use the order of operations.', r'Evaluate ⟨3x^2 - 4⟩ for x = 5.', [['Substitute:', r'⟨3(5)^2 - 4 = 3 \cdot 25 - 4⟩']], '71', N('3*5**2-4', 71)),
   MS('Quick Reminders & Common Mistakes', ['3x means 3 times x.', 'Exponents come before multiplying.', '“Less than” reverses the order: 8 less than y is y − 8.'],
      [[r'⟨2^3 = 6⟩', 'it is 2 · 2 · 2 = 8'], ['Adding before multiplying', 'multiply first'], ['8 less than y = 8 − y', 'y − 8']])],
  [EX('Equivalent Expressions', 'Use the distributive property and combine like terms.', 'Simplify 4(x + 3) + 2x.', [['Distribute:', '4x + 12 + 2x'], ['Combine:', '6x + 12']], '6x + 12', {'expr': '4*(x+3)+2*x', 'is': '6*x+12'}),
   TB('Properties', ['Property', 'Example'], [['Commutative', 'a + b = b + a'], ['Associative', '(ab)c = a(bc)'], ['Distributive', 'a(b + c) = ab + ac'], ['Identity', 'a + 0 = a, a · 1 = a']]),
   EX('Solving One-Step Equations', 'Undo the operation with its inverse. Do the same to both sides.', 'x + 9 = 23', [['Subtract 9:', 'x = 23 − 9']], 'x = 14', N('23-9', 14)),
   EX('Multiplication Equations', 'Divide both sides by the coefficient.', '6m = 42', [['Divide by 6:', r'⟨m = \tfrac{42}{6}⟩']], 'm = 7', N('42/6', 7)),
   TB('Independent and Dependent Variables', ['Situation', 'Independent → dependent'], [['Hours worked → pay', 'h → p'], ['Gallons bought → cost', 'g → c'], ['Minutes running → distance', 'm → d']],
      'Rule example: p = 15h (pay depends on hours).'),
   L('Check Yourself', ['Did I use PEMDAS in order?', 'Did I do the same thing to both sides?', 'Did I check by substituting my answer?', 'Did I combine only like terms?'])])

sheet('math6-inequalities', C, 5, 'Inequalities',
  'inequality symbols, solutions and graphs', 'solving one-step inequalities and applications',
  [V('Key Vocabulary', [
     ['inequality', 'Compares two values with <, >, ≤, ≥.', 'x > 4'],
     ['solution', 'A value that makes it true.', '6 is a solution of x > 4'],
     ['solution set', 'All values that make it true.', 'every number greater than 4'],
     ['open circle', 'Endpoint not included (< or >).', 'x < 2'],
     ['closed circle', 'Endpoint included (≤ or ≥).', 'x ≥ −1']]),
   TB('Symbols in Words', ['Words', 'Symbol'], [['at least, no less than', '≥'], ['at most, no more than', '≤'], ['more than, exceeds', '>'], ['fewer than, below', '<']]),
   EX('Testing Solutions', 'Substitute; if the statement is true, the value is a solution.', 'Is 7 a solution of 3x − 5 ≥ 16?', [['Substitute:', '3(7) − 5 = 16'], ['Check:', '16 ≥ 16 is true']], 'Yes', TRUE('3*7-5 >= 16')),
   W('Graphing on a Number Line', [['x > 3', 'open circle at 3, arrow right'], ['x ≤ −2', 'closed circle at −2, arrow left'], ['y ≥ 0', 'closed circle at 0, arrow right'], ['n < 5', 'open circle at 5, arrow left']]),
   W('Writing Inequalities from Graphs', [['Closed circle at 4, arrow left', 'x ≤ 4'], ['Open circle at −1, arrow right', 'x > −1'], ['Open circle at 0, arrow left', 'x < 0']]),
   MS('Quick Reminders & Common Mistakes', ['The arrow points the way the solutions go.', 'Many values can be solutions.', 'Check one value from your graph.'],
      [['Closed circle for <', 'use an open circle'], ['“At least 10” as x < 10', 'x ≥ 10'], ['Only listing one solution', 'describe all of them']])],
  [EX('Solving by Adding or Subtracting', 'Undo with the inverse operation on both sides.', 'x + 8 < 15', [['Subtract 8:', 'x < 7']], 'x < 7', TRUE('6+8 < 15 && !(7+8 < 15)')),
   EX('Solving by Multiplying or Dividing', 'Divide or multiply both sides by a positive number.', '4n ≥ 36', [['Divide by 4:', 'n ≥ 9']], 'n ≥ 9', TRUE('4*9 >= 36 && !(4*8.9 >= 36)')),
   EX('Fractions in Inequalities', 'Multiply both sides by the denominator.', r'⟨\tfrac{y}{3} \le 5⟩', [['Multiply by 3:', 'y ≤ 15']], 'y ≤ 15', TRUE('15/3 <= 5 && !(15.1/3 <= 5)')),
   EX('Applications', 'Write the inequality from the words, then solve.', 'You have $40 and tickets cost $6 each. How many can you buy?', [['Inequality:', '6t ≤ 40'], ['Divide:', r'⟨t \le 6.\overline{6}⟩']], 'at most 6 tickets', TRUE('6*6 <= 40 && 6*7 > 40')),
   TB('Whole-Number Answers', ['Context', 'Round'], [['Tickets, people, buses', 'Whole numbers only'], ['“At most” money left', 'Round down'], ['“At least” buses needed', 'Round up']], 'Always reread the question to decide.'),
   L('Check Yourself', ['Did I pick the right symbol for the words?', 'Open or closed circle?', 'Does a number from my graph make the inequality true?', 'Does my answer make sense in the story?'])])

sheet('math6-geometry', C, 6, 'Geometry',
  'area of quadrilaterals, triangles and composite polygons', 'volume, polygons on the coordinate plane, nets and surface area',
  [TB('Area Formulas', ['Figure', 'Area'], [['Rectangle', 'A = lw'], ['Parallelogram', 'A = bh'], ['Triangle', r'⟨A = \tfrac{1}{2}bh⟩'], ['Trapezoid', r'⟨A = \tfrac{1}{2}(b_1 + b_2)h⟩']], 'The height is perpendicular to the base.'),
   EX('Parallelograms', 'Use the base and the perpendicular height, not the slanted side.', 'Base 9 cm, height 5 cm, slanted side 6 cm.', [['A = bh:', '9 · 5']], '45 cm²', N('9*5', 45)),
   EX('Triangles', 'A triangle is half of a parallelogram.', 'Base 12 in, height 7 in.', [['Half of bh:', r'⟨\tfrac{1}{2} \cdot 12 \cdot 7⟩']], '42 in²', N('0.5*12*7', 42)),
   EX('Trapezoids', 'Average the two bases, then multiply by the height.', 'Bases 6 m and 10 m, height 4 m.', [['Formula:', r'⟨\tfrac{1}{2}(6 + 10)(4)⟩']], '32 m²', N('0.5*(6+10)*4', 32)),
   EX('Composite Figures', 'Split into rectangles and triangles, then add (or subtract a missing piece).', 'A 10 × 6 rectangle with a triangle (base 10, height 3) on top.', [['Rectangle:', '60'], ['Triangle:', r'⟨\tfrac{1}{2} \cdot 10 \cdot 3 = 15⟩']], '75 units²', N('10*6+0.5*10*3', 75)),
   MS('Quick Reminders & Common Mistakes', ['Area is in square units (cm²).', 'Volume is in cubic units (cm³).', 'Height makes a right angle with the base.'],
      [['Using the slanted side as height', 'use the perpendicular height'], ['Forgetting the ½ for triangles', r'⟨\tfrac{1}{2}bh⟩'], ['Square units for volume', 'cubic units']])],
  [EX('Volume of a Rectangular Prism', 'V = lwh (works for fractional edges too).', r'⟨2\tfrac{1}{2}⟩ ft by 4 ft by 3 ft', [['Multiply:', '2.5 · 4 · 3']], '30 ft³', N('2.5*4*3', 30)),
   EX('Polygons on the Coordinate Plane', 'Find side lengths by subtracting coordinates on the same line.', 'Rectangle with vertices (−2, 1), (4, 1), (4, 5), (−2, 5). Area?', [['Length:', '4 − (−2) = 6'], ['Width:', '5 − 1 = 4']], '24 units²', N('(4-(-2))*(5-1)', 24)),
   EX('Perimeter on a Grid', 'Add all side lengths.', 'Same rectangle: perimeter?', [['Add:', '6 + 4 + 6 + 4']], '20 units', N('2*(6+4)', 20)),
   EX('Nets and Surface Area', 'Unfold the solid into its faces and add their areas.', 'Surface area of a 5 × 3 × 2 box.', [['Pairs of faces:', '2(15) + 2(10) + 2(6)']], '62 units²', N('2*(5*3+5*2+3*2)', 62)),
   TB('Which Measure?', ['Question', 'Measure'], [['Fence around a garden', 'Perimeter'], ['Carpet for a floor', 'Area'], ['Wrapping paper for a box', 'Surface area'], ['Water in a tank', 'Volume']]),
   L('Check Yourself', ['Did I use the perpendicular height?', 'Did I include every face in the net?', 'Are my units squared or cubed correctly?', 'Did I split the composite figure without overlapping pieces?'])])

sheet('math6-data-displays', C, 7, 'Data Displays',
  'statistical questions, dot plots, histograms and box plots', 'mean, median, range, IQR, MAD and the shape of a distribution',
  [V('Key Vocabulary', [
     ['statistical question', 'Expects answers that vary.', 'How tall are 6th graders?'],
     ['distribution', 'How data values are spread out.', 'a dot plot of quiz scores'],
     ['mean', 'Sum ÷ number of values.', 'mean of 2, 4, 9 is 5'],
     ['median', 'Middle value of ordered data.', 'median of 2, 4, 9 is 4'],
     ['outlier', 'A value far from the others.', '45 in 10, 12, 11, 45']]),
   TB('Choosing a Display', ['Display', 'Best for'], [['Dot plot', 'small data sets; each value shown'], ['Histogram', 'large data in equal intervals'], ['Box plot', 'five-number summary, spread, comparing groups']]),
   EX('Mean', 'Add the values, then divide by how many there are.', 'Find the mean of 8, 12, 7, 9, 14.', [['Sum:', '50'], ['Divide:', '50 ÷ 5']], '10', N('(8+12+7+9+14)/5', 10)),
   EX('Median', 'Order the data. With an even count, average the two middle values.', 'Median of 3, 9, 4, 7, 10, 6.', [['Order:', '3, 4, 6, 7, 9, 10'], ['Middle two:', r'⟨\tfrac{6 + 7}{2}⟩']], '6.5', N('(6+7)/2', 6.5)),
   EX('Five-Number Summary', 'Minimum, Q1, median, Q3, maximum.', 'Data: 2, 4, 5, 7, 8, 10, 12, 15', [['Median:', r'⟨\tfrac{7 + 8}{2} = 7.5⟩'], ['Q1, Q3:', 'medians of each half: 4.5 and 11']], '2, 4.5, 7.5, 11, 15', [N('(7+8)/2', 7.5), N('(4+5)/2', 4.5), N('(10+12)/2', 11)]),
   MS('Quick Reminders & Common Mistakes', ['Order data before finding the median.', 'A histogram’s bars touch; intervals must be equal.', 'Outliers pull the mean, not the median.'],
      [['Median of unordered data', 'order it first'], ['Range = largest value', 'range = max − min'], ['Reading a box plot’s box as the whole data', 'the box is the middle 50%']])],
  [EX('Range and IQR', 'Range = max − min. IQR = Q3 − Q1 (spread of the middle half).', 'Using 2, 4.5, 7.5, 11, 15:', [['Range:', '15 − 2 = 13'], ['IQR:', '11 − 4.5 = 6.5']], 'range 13, IQR 6.5', [N('15-2', 13), N('11-4.5', 6.5)]),
   EX('Mean Absolute Deviation', 'Find the mean, the distance of each value from it, then the mean of those distances.', 'MAD of 2, 4, 6, 8.', [['Mean:', '5'], ['Distances:', '3, 1, 1, 3']], 'MAD = 2', N('(3+1+1+3)/4', 2)),
   TB('Shape of a Distribution', ['Shape', 'Mean vs. median'], [['Symmetric', 'about equal'], ['Skewed right (long tail right)', 'mean > median'], ['Skewed left (long tail left)', 'mean < median']]),
   W('Best Measure of Center and Spread', [['Symmetric, no outliers', 'mean and MAD'], ['Skewed or has outliers', 'median and IQR'], ['Comparing two box plots', 'medians and IQRs']]),
   W('Describing a Distribution', [['Center', 'mean or median'], ['Spread', 'range, IQR or MAD'], ['Shape', 'symmetric, skewed, clusters, gaps'], ['Unusual values', 'outliers']]),
   L('Check Yourself', ['Is my question statistical (answers vary)?', 'Did I order the data first?', 'Did I choose the center that fits the shape?', 'Does my answer include units?'])])
